import {FISH} from './fish-config.js';import {fishSupply} from './fish-state.js';import {fishPayment} from './fish-feed.js';
/** @param {import('./engine.js').State} state @param {import('./fish-feed.js').FishTransaction} transact @returns {string|undefined} */
function buyWater(state,transact){const g=state.fish;if(!g)return 'fishNotVisited';if(fishSupply(g.water)+FISH.exchangeL>4000)return 'fishWaterFull';if(state.coins<FISH.exchangeCoins)return 'fishNoWater';fishPayment(state,'fish.water_purchase',-FISH.exchangeCoins,'water.0',transact);g.water.normal+=FISH.exchangeL;g.stats.waterBoughtL+=FISH.exchangeL;}
/** Fixed5% well-mixed exchange. Integer-floor effluent leaves rounding mass in pond. @param {import('./engine.js').State} state @param {import('./engine.js').Command} command @param {import('./fish-feed.js').FishTransaction} transact @returns {string|undefined} */
export function fishWaterCommand(state,command,transact){const g=state.fish,p=g?.ponds.find(v=>v.id===command.fishPond);if(!g||!p)return 'fishPondMissing';if(command.type==='fish.buyWater')return buyWater(state,transact);if(fishSupply(g.water)<FISH.exchangeL){const error=buyWater(state,transact);if(error)return error;}let remaining=FISH.exchangeL;for(const source of /** @type {const} */(['recovery','starter','normal'])){const take=Math.min(remaining,g.water[source]);g.water[source]-=take;g.stats[source+'WaterUsedL']+=take;remaining-=take;}const oxygenOut=Math.floor(p.oxygenMg*FISH.exchangeL/p.volumeL),tanOut=Math.floor(p.tanMg*FISH.exchangeL/p.volumeL),sludgeOut=Math.floor(p.sludgeG*FISH.exchangeL/p.volumeL),oxygenIn=FISH.exchangeL*FISH.sourceDoMgL;p.oxygenMg+=oxygenIn-oxygenOut;p.tanMg-=tanOut;p.sludgeG-=sludgeOut;p.balance.oxygenInMg+=oxygenIn;p.balance.oxygenWaterInMg+=oxygenIn;p.balance.oxygenOutMg+=oxygenOut;p.balance.oxygenEffluentMg+=oxygenOut;p.balance.tanRemovedMg+=tanOut;p.balance.tanEffluentMg+=tanOut;p.balance.sludgeEffluentG+=sludgeOut;p.balance.exchangedL+=FISH.exchangeL;p.balance.waterInL+=FISH.exchangeL;p.balance.waterOutL+=FISH.exchangeL;g.stats.exchanges++;}
